function validate([s, dictionary]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's uses only lowercase English letters.';
  if (!Array.isArray(dictionary) || dictionary.length < 1 || dictionary.length > 1000) return 'dictionary needs 1 to 1000 words.';
  for (const word of dictionary) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 1000) return 'Each word has 1 to 1000 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use only lowercase English letters.';
  }
  return null;
}

