function findLongestWord(s, dictionary) {
  let best = '';

  for (const word of dictionary) {
    let i = 0;
    let j = 0;
    while (i < s.length && j < word.length) {
      if (s[i] === word[j]) {
        j++;
      }
      i++;
    }
    if (j < word.length) {
      continue;
    }
    if (word.length > best.length || (word.length === best.length && word < best)) {
      best = word;
    }
  }
  return best;
}

