function findLongestWord(s, dictionary) {
  const ranked = [...dictionary].sort((a, b) => (b.length - a.length) || (a < b ? -1 : a > b ? 1 : 0));
  for (const word of ranked) {
    let from = 0;
    let ok = true;
    for (const ch of word) {
      const at = s.indexOf(ch, from);
      if (at < 0) { ok = false; break; }
      from = at + 1;
    }
    if (ok) return word;
  }
  return '';
}

