function generate(rand, size) {
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abc'.slice(0, 2 + Math.floor(rand() * 2));
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const randomWord = len => Array.from({ length: len }, pick).join('');
  const fromS = (s, len) => {
    const keep = [];
    for (let i = 0; i < s.length; i++) keep.push(i);
    while (keep.length > len) keep.splice(Math.floor(rand() * keep.length), 1);
    return keep.map(i => s[i]).join('');
  };
  if (size === 'large') {
    const s = randomWord(1000);
    const dictionary = [];
    for (let k = 0; k < 300; k++) {
      if (rand() < 0.3) dictionary.push(fromS(s, 1 + Math.floor(rand() * 25)));
      else dictionary.push(randomWord(1 + Math.floor(rand() * 25)));
    }
    return [s, dictionary];
  }
  const s = randomWord(1 + Math.floor(rand() * 9));
  const count = 1 + Math.floor(rand() * 6);
  const dictionary = [];
  for (let k = 0; k < count; k++) {
    if (rand() < 0.4) dictionary.push(fromS(s, 1 + Math.floor(rand() * s.length)));
    else dictionary.push(randomWord(1 + Math.floor(rand() * 4)));
  }
  return [s, dictionary];
}
